-- Monde extérieur : tableaux de primes, boss élite de zone, boss rare (généré)
SET NAMES utf8mb4;
DELETE FROM gameobject WHERE id BETWEEN 990500 AND 990599;
DELETE FROM gameobject_template WHERE entry BETWEEN 990500 AND 990599;
DELETE FROM gameobject_questrelation WHERE id BETWEEN 990500 AND 990599;
DELETE FROM gameobject_involvedrelation WHERE id BETWEEN 990500 AND 990599;
DELETE FROM quest_template WHERE entry BETWEEN 991400 AND 991999;
DELETE FROM creature WHERE id BETWEEN 992000 AND 992199;
DELETE FROM creature_template WHERE Entry BETWEEN 992000 AND 992199;
DELETE FROM creature_loot_template WHERE entry BETWEEN 992000 AND 992199;
DELETE FROM reference_loot_template WHERE entry BETWEEN 993000 AND 993299;

