UPDATE creature_template SET Name=CONCAT('Chef ', Name) WHERE Entry BETWEEN 992000 AND 992099;
UPDATE creature_template SET Name=CONCAT(Name, ' alpha') WHERE Entry BETWEEN 992100 AND 992199;

-- Quêtes des tableaux (textes complétés plus bas avec les noms de la base)

-- Textes en français avec les noms de la base
DROP TEMPORARY TABLE IF EXISTS tmp_zn;
CREATE TEMPORARY TABLE tmp_zn (id INT PRIMARY KEY, n VARCHAR(100)) CHARACTER SET utf8mb4;
UPDATE quest_template q JOIN creature_template c ON c.Entry=q.ReqCreatureOrGOId1 JOIN tmp_zn z ON z.id=q.ZoneOrSort SET q.Title=CONCAT('Prime : ', c.Name), q.Objectives=CONCAT('Tuez ', q.ReqCreatureOrGOCount1, ' x ', c.Name, '.'), q.Details=CONCAT('Avis aux aventuriers de la région de ', z.n, ' : les ', c.Name, ' deviennent trop nombreux. ','Une prime est offerte à qui en éliminera ', q.ReqCreatureOrGOCount1, '.$B$BRevenez au tableau une fois le travail fait.') WHERE q.entry BETWEEN 991400 AND 991999 AND q.ReqCreatureOrGOId1>0;
UPDATE quest_template q JOIN item_template i ON i.entry=q.ReqItemId1 JOIN tmp_zn z ON z.id=q.ZoneOrSort SET q.Title=CONCAT('Récolte : ', i.name), q.Objectives=CONCAT('Rapportez ', q.ReqItemCount1, ' x ', i.name, '.'), q.Details=CONCAT('Un marchand de ', z.n, ' paie bien pour ', q.ReqItemCount1, ' x ', i.name, '. ','On en trouve sur les créatures des environs.$B$BRapportez-les au tableau de primes.') WHERE q.entry BETWEEN 991400 AND 991999 AND q.ReqItemId1>0;
UPDATE quest_template q JOIN creature_template c ON c.Entry=q.ReqCreatureOrGOId1 JOIN tmp_zn z ON z.id=q.ZoneOrSort SET q.Title=CONCAT('Avis de recherche : ', c.Name), q.Objectives=CONCAT('Abattez ', c.Name, '.'), q.Details=CONCAT(c.Name, ' terrorise la région de ', z.n, '. Il est redoutable : partez à plusieurs.$B$B','Rapportez la preuve de sa mort au tableau et choisissez votre récompense.') WHERE q.entry BETWEEN 991400 AND 991999 AND q.ReqCreatureOrGOId1 BETWEEN 992000 AND 992199;
DROP TEMPORARY TABLE tmp_zn;

SELECT 'Monde exterieur OK' AS resultat;
